1	export type Item = {
2	  type: string;
3	};
4	
5	export type QuoteStep = {
6	  op: "quote";
7	  items: Item[];
8	};
9	
10	export type Scenario = {
11	  customer: { yearsWithMHPCO: number };
12	  steps: QuoteStep[];
13	};
14	
15	export type ScenarioResults = {
16	  results: unknown[];
17	};
18	
19	const PROCESSING_FEE = 5;
20	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	};
27	
28	const policyBasePremium = (items: Item[]): number =>
29	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
30	
31	const quote = (step: QuoteStep): { premium: number } => {
32	  const basePremium = policyBasePremium(step.items);
33	  const assessedPremium = basePremium + basePremium * INITIAL_ASSESSMENT_SURCHARGE;
34	
35	  return { premium: assessedPremium + PROCESSING_FEE };
36	};
37	
38	export const runScenario = (scenario: Scenario): ScenarioResults => ({
39	  results: scenario.steps.map(quote),
40	});
41

